func minKBitFlips(nums []int, k int) int {
    res := 0
    for i:=0; i < len(nums); i++ {
        if nums[i] == 1 {
            continue
        }
        
        j := 0
        for ;j < k && (i+j) < len(nums); j++ {
            nums[i+j] ^= 1
        }
        
        
        if j != k {
            return -1
        }
        res+=1
    }
    
    return res
}